const $=s=>document.querySelector(s);
const icons={home:'M3 10 12 3l9 7v11H3Z M9 21v-8h6v8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',scan:'M8 3H3v5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5 M7 7h3v3H7Z M14 7h3v3h-3Z M7 14h3v3H7Z M14 14v3h3v-3Z',bag:'M5 7h14l2 14H3Z M8 7V5a4 4 0 0 1 8 0v2',chart:'M4 20V10 M10 20V4 M16 20v-8 M22 20V7',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10a8 8 0 1 0-16 0 8 8 0 0 0 16 0',clock:'M12 8v4l3 2 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 0-6 0 3 3 0 0 0 6 0',check:'m5 12 4 4L19 6',exit:'M9 4H3v16h6 M9 12h12 M16 7l5 5-5 5',card:'M2 5h20v14H2Z M2 10h20 M6 15h3',box:'m12 2 10 5v10l-10 5-10-5V7Z M2 7l10 5 10-5 M12 12v10',reset:'M3 11a9 9 0 1 1 2 7 M3 3v8h8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.home}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'});
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Conakry'});
const shift=(days,from=today())=>{let d=new Date(from+'T12:00:00');d.setDate(d.getDate()+days);return d.toLocaleDateString('en-CA')};
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2,8);
const planPrices={Standard:35,Premium:100,VIP:150};
function seed(){const names=['Aïssatou Diallo','Mamadou Barry','Fatoumata Camara','Ibrahima Bah','Mariama Condé','Oumar Sow','Aminata Sylla','Alpha Diallo'];const plans=['Premium','VIP','Standard','Standard','Premium','Standard','VIP','Standard'];let members=names.map((name,i)=>({id:'OD-'+String(i+1).padStart(3,'0'),name,phone:'',plan:plans[i],expiry:shift(i===4?-2:i===7?3:25+i),created:shift(-20),visits:i+4}));return{version:1,members,products:[{id:'p1',name:'T-shirt Essential',category:'Vêtements',price:18,stock:24,art:'shirt',color:'#68775e'},{id:'p2',name:'Gourde Orion · 750 ml',category:'Accessoires',price:12,stock:18,art:'bottle',color:'#c6b085'},{id:'p3',name:'Gants Training',category:'Accessoires',price:15,stock:3,art:'gloves',color:'#3d4541'},{id:'p4',name:'Sac de sport District',category:'Accessoires',price:28,stock:8,art:'bag',color:'#8a806b'},{id:'p5',name:'Tapis de yoga',category:'Petit matériel',price:22,stock:12,art:'mat',color:'#a0ad92'},{id:'p6',name:'Barre énergie · cacao',category:'Nutrition',price:3,stock:32,art:'bar',color:'#aa8860'}],entries:[{id:uid(),memberId:'OD-002',name:names[1],plan:'VIP',time:today()+'T09:42:00',out:null,guest:false},{id:uid(),memberId:'OD-001',name:names[0],plan:'Premium',time:today()+'T09:35:00',out:null,guest:false},{id:uid(),memberId:'OD-003',name:names[2],plan:'Standard',time:today()+'T08:50:00',out:today()+'T09:30:00',guest:false}],orders:[],payments:[]}}
let state;try{state=JSON.parse(localStorage.getItem('orion-demo-v1'))}catch{}if(!state||state.version!==1)state=seed();
let page='dashboard',search='',filter='Tous',cart={},selectedMember='OD-001',shopCustomer='walkin',shopMode='catalog',accessMessage=null;
function save(){try{localStorage.setItem('orion-demo-v1',JSON.stringify(state))}catch{toast('Stockage local indisponible : les modifications restent dans cette session.')}}
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
const planBadge=p=>`<span class="badge ${(p||'sans').toLowerCase()}">${esc(p||'Sans abonnement')}</span>`;
const person=m=>`<div class="person"><span class="avatar">${esc(initials(m.name))}</span><div>${esc(m.name)}<small>${esc(m.id)}</small></div></div>`;
const navs=[['dashboard','home','Vue d’ensemble'],['entries','scan','Entrées & sorties'],['clients','users','Clients'],['shop','bag','Boutique'],['member','card','Espace membre']];
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function heading(title,subtitle,buttons=''){return`<div class="pageheading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${buttons}</div></div>`}
function button(label,action,type='primary',sym='plus'){return`<button class="btn ${type}" onclick="${action}">${icon(sym)}${label}</button>`}
function dashboard(){if(!can('dashboard'))return deny();let onSite=state.entries.filter(e=>!e.out).length,dayEntries=state.entries.filter(e=>e.time.startsWith(today())).length,shopSales=state.orders.filter(o=>o.time.startsWith(today())).reduce((s,o)=>s+o.total,0),numActive=state.members.filter(active).length;return heading('Le club, au quotidien.',new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})+' · Une belle journée commence ici.',button('Nouveau client','newClient()','','plus')+button('Enregistrer une entrée',"go('entries')",'primary','scan'))+`<section class="hero"><img src="building.png" alt="Façade du complexe Orion District, avec salle de fitness à l’étage et boutique au rez-de-chaussée"><div class="herocopy"><div class="eyebrow">Bienvenue à Orion District</div><h2>Un lieu pour bouger.<br>Une équipe pour avancer.</h2><p>Votre salle, vos membres et votre boutique, réunis au même endroit.</p><div class="herofoot"><span>${icon('pin')}Sonfonia T7 · Conakry</span><span>${icon('clock')}6 h – 23 h envisagés</span></div></div><span class="phototag">Le futur complexe · Vue du projet</span></section><section class="stats"><div class="stat"><div class="stathead">Membres actifs ${icon('users')}</div><div class="statvalue">${numActive}<span> / ${state.members.length}</span></div><div class="statnote"><strong>${state.members.filter(m=>!active(m)).length} à renouveler</strong> · comptes de démonstration</div></div><div class="stat"><div class="stathead">Présents au club ${icon('scan')}</div><div class="statvalue">${onSite}<span> personnes</span></div><div class="statnote"><strong>Accès suivi</strong> · entrées et sorties</div></div><div class="stat"><div class="stathead">Entrées aujourd’hui ${icon('chart')}</div><div class="statvalue">${dayEntries}</div><div class="statnote">Membres et invités enregistrés</div></div><div class="stat"><div class="stathead">Boutique aujourd’hui ${icon('bag')}</div><div class="statvalue">${money(shopSales)}</div><div class="statnote"><strong>${state.orders.filter(o=>o.time.startsWith(today())).length} commande(s)</strong> · ventes simulées</div></div></section><div class="dashgrid"><section class="panel"><div class="panelhead"><div><h2>Les derniers passages</h2><p>Le rythme de votre club, en un coup d’œil.</p></div><button class="textbtn" onclick="go('entries')">Tout voir ${icon('arrow')}</button></div>${entryTable(state.entries.slice(0,5),false)}<div class="quick"><span class="iconbox">${icon('users')}</span><div><h3>Chaque membre compte.</h3><p>Retrouvez les abonnements et les renouvellements.</p></div><button class="textbtn" aria-label="Ouvrir les clients" onclick="go('clients')">${icon('arrow')}</button></div></section><section class="panel"><div class="panelhead"><div><h2>Fréquentation du jour</h2><p>Entrées enregistrées par créneau horaire</p></div><span class="badge green">Aujourd’hui</span></div>${chart()}<div class="chartlegend"><span><span class="dot"></span>Activité de démonstration</span><b>${dayEntries} passages</b></div><div class="quick"><span class="iconbox">${icon('box')}</span><div><h3>${state.products.filter(p=>p.stock<5).length} article(s) à surveiller</h3><p>Le stock boutique mérite un coup d’œil.</p></div><button class="textbtn" aria-label="Voir les stocks" onclick="shopMode='stock';go('shop')">${icon('arrow')}</button></div></section></div>`}
function chart(){const bins=[6,9,12,15,18,21];const counts=bins.map(h=>state.entries.filter(e=>e.time.startsWith(today())&&new Date(e.time).getHours()>=h&&new Date(e.time).getHours()<h+3).length);let max=Math.max(...counts,1);return`<div class="chart" role="img" aria-label="${bins.map((h,i)=>h+' h : '+counts[i]+' entrées').join(', ')}">${bins.map((h,i)=>`<div class="barwrap"><span class="subtle">${counts[i]||''}</span><div class="bar ${counts[i]?'current':''}" style="height:${Math.max(4,counts[i]/max*78)}px"></div><small>${h} h</small></div>`).join('')}</div>`}
function entryTable(list,controls=true){return`<div class="tablewrap"><table><thead><tr><th>Membre</th><th>Formule</th><th>Entrée</th><th>Statut</th>${controls?'<th></th>':''}</tr></thead><tbody>${list.length?list.map(e=>`<tr><td>${person({name:e.name,id:e.guest?'Invité de '+e.memberId:e.memberId})}</td><td>${planBadge(e.plan)}</td><td>${e.time.startsWith(today())?'':date(e.time.slice(0,10))+' · '}${new Date(e.time).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</td><td><span class="badge ${e.out?'gray':'green'}">${e.out?'Sorti':'Au club'}</span></td>${controls?`<td>${!e.out?`<button class="btn small" onclick="exitEntry('${e.id}')">Sortie ${icon('exit')}</button>`:''}</td>`:''}</tr>`).join(''):`<tr><td colspan="5" class="empty">Aucun passage enregistré.</td></tr>`}</tbody></table></div>`}
function entries(){if(!can('entries'))return deny();return heading('Bienvenue au club.','Contrôlez un abonnement et enregistrez les passages.',button('Nouveau client','newClient()','','plus'))+`<div class="entrygrid"><section class="panel scanner"><div class="scanframe">${icon('scan')}</div><h2>Contrôle d’accès</h2><p>Saisissez un code membre ou choisissez un compte pour simuler son passage.</p><form onsubmit="event.preventDefault();checkIn()"><div class="field"><label for="code">Code membre ou contenu du QR</label><input id="code" placeholder="OD-006 ou ORION:…" autocomplete="off" value=""></div><div class="field"><label for="accessSelect">Ou sélectionner un membre</label><select id="accessSelect"><option value="">Choisir un membre</option>${state.members.map(m=>`<option value="${m.id}">${esc(m.name)} · ${m.plan}${active(m)?'':' · expiré'}</option>`).join('')}</select></div><button class="btn primary" type="submit">${icon('scan')}Valider l’entrée</button></form><div class="notice">Démo : saisissez un code membre ou le texte décodé du QR Orion. Le scan physique et le tourniquet restent à connecter.</div>${accessMessage?`<div class="result ${accessMessage.error?'error':''}" role="status">${esc(accessMessage.text)}</div>`:''}</section><section class="panel"><div class="panelhead"><div><h2>Journal des passages</h2><p>${state.entries.filter(e=>!e.out).length} personne(s) actuellement au club</p></div><span class="badge green">${state.entries.length} passages</span></div>${entryTable(state.entries)}</section></div>`}
function manualCheckIn(){if(!can('entries'))return deny();const code=($('#code').value.trim()||$('#accessSelect').value).toUpperCase();let m=state.members.find(m=>m.id===code);if(!m){accessMessage={error:true,text:'Code non reconnu. Choisissez un compte de démonstration.'};render();return}if(!active(m)){accessMessage={error:true,text:`Accès refusé : l’abonnement de ${m.name} a expiré le ${date(m.expiry)}. Un renouvellement est nécessaire.`};render();return}if(state.entries.some(e=>e.memberId===m.id&&!e.guest&&!e.out)){accessMessage={error:true,text:`${m.name} est déjà au club. Enregistrez sa sortie avant une nouvelle entrée.`};render();return}state.entries.unshift({id:uid(),memberId:m.id,name:m.name,plan:m.plan,time:new Date().toISOString(),out:null,guest:false});m.visits++;save();accessMessage={text:`Entrée autorisée. Bienvenue ${m.name} ! Abonnement ${m.plan} valide jusqu’au ${date(m.expiry)}.`};render()}
function exitEntry(id){if(!can('entries'))return deny();const e=state.entries.find(e=>e.id===id);e.out=new Date().toISOString();if(!e.guest)state.entries.filter(x=>x.memberId===e.memberId&&x.guest&&!x.out).forEach(x=>x.out=e.out);save();render();toast('Sortie enregistrée. À très bientôt !')}
function searchbar(placeholder){return`<div class="search">${icon('search')}<input id="search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(search)}"></div>`}
function bindSearch(){let s=$('#search');if(s)s.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)})}
function clientsBase(){if(!can('clients'))return deny();let list=state.members.filter(m=>(m.name+' '+m.id+' '+m.phone).toLowerCase().includes(search.toLowerCase())&&(filter==='Tous'||filter==='Actifs'&&active(m)||filter==='À renouveler'&&!active(m)));return heading('Vos membres, votre communauté.','Abonnements, coordonnées et activité de chaque client.',button('Ajouter un client','newClient()'))+`<div class="toolbar">${searchbar('Rechercher un nom ou un code…')}<div class="tabs">${['Tous','Actifs','À renouveler'].map(t=>`<button class="${t===filter?'active':''}" onclick="filter='${t}';render()">${t}</button>`).join('')}</div></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Membre</th><th>Abonnement</th><th>Valide jusqu’au</th><th>Statut</th><th>Visites</th><th></th></tr></thead><tbody>${list.map(m=>`<tr><td>${person(m)}</td><td>${planBadge(m.plan)}</td><td>${m.expiry?date(m.expiry):'—'}</td><td><span class="badge ${active(m)?'green':'red'}">${active(m)?'Actif':'Expiré'}</span></td><td>${m.visits}</td><td><button class="btn small" onclick="profile('${m.id}')">Voir la fiche ${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Aucun client ne correspond à votre recherche.</td></tr>'}</tbody></table></div></section><div class="notice">Formules issues du business plan : Standard 35 $ / mois, Premium 100 $ / mois, VIP 150 $ / mois. Grille en GNF à valider avant le lancement.</div>`}
function modal(title,body){$('#modal').innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="close" aria-label="Fermer" onclick="$('#modal').close()">×</button></div><div class="modalbody">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function newClient(){if(!can('clients'))return deny();modal('Bienvenue chez Orion',`<form id="newclient" onsubmit="event.preventDefault();createClient()"><div class="field"><label for="clientName">Nom complet</label><input id="clientName" name="name" required maxlength="80" placeholder="Prénom et nom" autocomplete="name"></div><div class="field"><label for="clientPhone">Téléphone (facultatif)</label><input id="clientPhone" name="phone" type="tel" maxlength="25" placeholder="+224 …" autocomplete="tel"></div><div class="field"><label for="clientPlan">Formule mensuelle</label><select id="clientPlan" name="plan">${Object.entries(planPrices).map(([p,n])=>`<option value="${p}">${p} · ${money(n)} / mois</option>`).join('')}</select></div><p class="subtle">Création d’un compte fictif avec un abonnement de 30 jours. Aucun paiement réel n’est prélevé.</p><div class="actions"><button type="button" class="btn" onclick="$('#modal').close()">Annuler</button><button class="btn primary">Créer le compte</button></div></form>`)}
function createClient(){if(!can('clients'))return deny();let f=new FormData($('#newclient')),name=f.get('name').trim();if(!name){toast('Renseignez le nom du client.');return}let n=Math.max(...state.members.map(m=>Number(m.id.slice(3))))+1;let m={id:'OD-'+String(n).padStart(3,'0'),name,phone:f.get('phone').trim(),plan:f.get('plan'),expiry:shift(30),created:today(),visits:0};m.email=m.id.toLowerCase()+'@exemple.test';state.members.push(m);migrate();state.payments.push({id:uid(),memberId:m.id,total:planPrices[m.plan],time:new Date().toISOString(),type:'Inscription'});save();$('#modal').close();go('clients');toast(`Compte ${m.id} créé · ${m.name}`)}
function editClient(id){if(!can('clients'))return deny();const m=state.members.find(m=>m.id===id);modal('Modifier le compte',`<form id="editclient" onsubmit="event.preventDefault();saveClient('${id}')"><div class="field"><label for="editName">Nom complet</label><input id="editName" name="name" required maxlength="80" value="${esc(m.name)}"></div><div class="field"><label for="editPhone">Téléphone</label><input id="editPhone" name="phone" type="tel" maxlength="25" value="${esc(m.phone)}"></div><div class="actions"><button class="btn primary">Enregistrer</button></div></form>`)}
function saveClient(id){if(!can('clients'))return deny();let f=new FormData($('#editclient')),m=state.members.find(m=>m.id===id);if(!f.get('name').trim())return;m.name=f.get('name').trim();m.phone=f.get('phone').trim();save();render();profile(id);toast('Coordonnées mises à jour.')}
function renewConfirm(id){if(!can('clients'))return deny();const m=state.members.find(m=>m.id===id);modal('Renouveler l’abonnement',`<p>Ajouter 30 jours à l’abonnement ${esc(m.plan)} de ${esc(m.name)} pour ${money(planPrices[m.plan])} ?</p><div class="notice">Paiement simulé. Aucun prélèvement réel.</div><div class="actions"><button class="btn" onclick="profile('${id}')">Retour</button><button class="btn primary" onclick="renew('${id}')">Confirmer le renouvellement</button></div>`)}
function renew(id){if(!can('clients'))return deny();let m=state.members.find(m=>m.id===id);m.expiry=shift(30,active(m)?m.expiry:today());state.payments.push({id:uid(),memberId:id,total:planPrices[m.plan],time:new Date().toISOString(),type:'Renouvellement'});save();render();profile(id);toast('Abonnement renouvelé pour 30 jours.')}
function art(p){const c=p.color;let body={shirt:`<path d="M46 25 25 37 11 64 34 76 43 62v68h75V62l9 14 24-12-15-27-21-12-22 9H68Z" fill="${c}"/><path d="M68 29q12 22 25 0" fill="none" stroke="#d8dfce" stroke-width="4"/><path d="M82 55v21m-7-11h14" stroke="#d9ceac" stroke-width="2"/>`,bottle:`<rect x="64" y="14" width="33" height="18" rx="5" fill="#39453a"/><rect x="56" y="30" width="49" height="109" rx="17" fill="${c}"/><path d="M62 47v65" stroke="#f9f3dd" stroke-opacity=".4" stroke-width="3"/><path d="m80 65 6 12-6 12-6-12Z" fill="#4c5344"/><text x="80" y="108" text-anchor="middle" font-size="7" letter-spacing="2" fill="#4c5344">ORION</text>`,gloves:`<g transform="rotate(-18 80 80)"><path d="M26 54v-22q8-13 13 0v16-25q8-13 13 0v22-20q9-12 13 0v26q12-8 15 0l-7 28-6 18H30l-9-25q-5-14 5-18Z" fill="${c}"/><rect x="28" y="95" width="40" height="22" rx="4" fill="#6f7b68"/><path d="M97 73V50q8-13 13 0v18-25q8-13 13 0v22-20q9-12 13 0v26q12-8 15 0l-7 28-6 18h-37l-9-25q-5-14 5-19Z" fill="${c}"/><rect x="99" y="115" width="40" height="22" rx="4" fill="#6f7b68"/></g>`,bag:`<path d="M23 60q57-12 114 0l9 60q-65 17-132 0Z" fill="${c}"/><path d="M56 61V42q25-25 48 0v19" fill="none" stroke="#3e473b" stroke-width="8"/><path d="M25 73h112 M45 59v67m73-67v67" stroke="#cec4af" stroke-width="3"/><rect x="65" y="85" width="35" height="18" rx="3" fill="#4a5145"/><text x="83" y="97" text-anchor="middle" font-size="6" letter-spacing="1" fill="#ece8db">ORION</text>`,mat:`<path d="m26 85 75-49 50 39-78 58Z" fill="${c}"/><g stroke="#e3e8d9" opacity=".4"><path d="m40 84 64-42m-55 48 64-42m-53 49 64-42m-53 49 64-42"/></g><path d="M25 85q20-16 39 8l10 25q4 27-21 19L25 110q-12-12 0-25Z" fill="#7d8c70"/><ellipse cx="57" cy="119" rx="12" ry="16" transform="rotate(-36 57 119)" fill="#b5c1a7"/><path d="M52 110q13 1 12 15-10 8-13-5" fill="none" stroke="#6e7c61" stroke-width="2"/>`,bar:`<g transform="rotate(-22 80 80)"><path d="M20 55h120v56H20Z" fill="${c}"/><path d="M20 55h15v56H20Zm105 0h15v56h-15Z" fill="#c9b78f"/><path d="M24 57v52m5-52v52m101-52v52m5-52v52" stroke="#8d7652"/><text x="80" y="77" text-anchor="middle" font-size="11" font-weight="bold" fill="#faf5e5">ENERGY</text><text x="80" y="94" text-anchor="middle" font-size="6" letter-spacing="2" fill="#faf5e5">CACAO · ORION</text></g>`};return`<svg viewBox="0 0 160 155" role="img" aria-label="Illustration ${esc(p.name)}">${body[p.art]||body.bag}</svg>`}
function addCart(id){let p=state.products.find(p=>p.id===id);if((cart[id]||0)>=p.stock){toast('Tout le stock disponible est déjà dans votre panier.');return}cart[id]=(cart[id]||0)+1;render();toast(`${p.name} ajouté au panier`)}
function changeQty(id,d){let p=state.products.find(p=>p.id===id);cart[id]=Math.max(0,Math.min(p.stock,(cart[id]||0)+d));if(!cart[id])delete cart[id];render()}
function stockPage(){if(!can('stock'))return deny();return`<div class="toolbar"><p class="muted">${state.products.length} références · modifiez les prix et les quantités disponibles.</p>${button('Nouvel article','newProduct()')}</div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Article</th><th>Catégorie</th><th>Prix ($)</th><th>Stock</th><th></th></tr></thead><tbody>${state.products.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.category)}</td><td><input class="stockinput" type="number" id="price-${p.id}" aria-label="Prix de ${esc(p.name)}" min="0.01" max="100000" step=".01" value="${p.price}"></td><td><input class="stockinput" type="number" id="stock-${p.id}" aria-label="Stock de ${esc(p.name)}" min="0" max="100000" step="1" value="${p.stock}"></td><td><button class="btn small" onclick="updateStock('${p.id}')">Enregistrer</button></td></tr>`).join('')}</tbody></table></div></section>`}
function updateStock(id){if(!can('stock'))return deny();let pi=$('#price-'+id),st=$('#stock-'+id);if(!pi.checkValidity()||!st.checkValidity()||!pi.value||!st.value){toast('Saisissez un prix positif et un stock entier entre 0 et 100 000.');return}let p=state.products.find(p=>p.id===id);p.price=Number(pi.value);p.stock=Number(st.value);if(cart[id]>p.stock){cart[id]=p.stock;if(!cart[id])delete cart[id]}save();render();toast('Article mis à jour.')}
function newProduct(){if(!can('stock'))return deny();modal('Ajouter un article',`<form id="productform" onsubmit="event.preventDefault();createProduct()"><div class="field"><label for="productName">Nom de l’article</label><input id="productName" name="name" required maxlength="70"></div><div class="field"><label for="productCategory">Catégorie</label><select id="productCategory" name="category">${['Vêtements','Accessoires','Petit matériel','Nutrition'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="formrow"><div class="field"><label for="productPrice">Prix indicatif ($)</label><input id="productPrice" type="number" name="price" min=".01" max="100000" step=".01" required></div><div class="field"><label for="productStock">Stock initial</label><input id="productStock" type="number" name="stock" min="0" max="100000" step="1" required></div></div><div class="actions"><button class="btn primary">Créer l’article</button></div></form>`)}
function createProduct(){if(!can('stock'))return deny();let f=new FormData($('#productform'));if(!f.get('name').trim())return;state.products.push({id:'p'+uid(),name:f.get('name').trim(),category:f.get('category'),price:Number(f.get('price')),stock:Number(f.get('stock')),art:({'Vêtements':'shirt','Accessoires':'bag','Petit matériel':'mat','Nutrition':'bar'})[f.get('category')],color:'#8a997a'});save();$('#modal').close();render();toast('Article ajouté au catalogue.')}
function ordersPage(){if(!can('sales'))return deny();return`<section class="panel"><div class="panelhead"><h2>Commandes boutique</h2><span class="badge">${state.orders.length} commande(s)</span></div><div class="tablewrap"><table><thead><tr><th>Commande</th><th>Client</th><th>Articles</th><th>Total</th><th>Statut</th><th></th></tr></thead><tbody>${state.orders.map(o=>`<tr><td>${o.id}<br><small>${date(o.time.slice(0,10))}</small></td><td>${esc(state.members.find(m=>m.id===o.memberId)?.name||'Client de passage')}</td><td>${o.items.map(i=>esc(i.name)+' × '+i.qty).join('<br>')}</td><td>${money(o.total)}</td><td><span class="badge ${o.status==='Retirée'?'green':'vip'}">${o.status}</span></td><td>${o.status!=='Retirée'?`<button class="btn small" onclick="collectOrder('${o.id}')">Marquer retirée</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Vos commandes apparaîtront ici après un achat dans la boutique.</td></tr>'}</tbody></table></div></section>`}
function collectOrder(id){if(!can('sales'))return deny();state.orders.find(o=>o.id===id).status='Retirée';save();render();toast('Retrait enregistré.')}
function resetDemo(){if(!can('settings'))return deny();modal('Recommencer la démonstration',`<p>Les clients ajoutés, commandes et passages de cette démo seront remplacés par les exemples initiaux.</p><div class="actions"><button class="btn" onclick="$('#modal').close()">Annuler</button><button class="btn primary" onclick="doReset()">Réinitialiser</button></div>`)}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
const roles={admin:{label:'Administrateur',pages:['dashboard','entries','clients','services','shop','team','settings'],description:'Tous les espaces, comptes d’équipe et paramètres.'},manager:{label:'Manager',pages:['dashboard','entries','clients','services','shop'],description:'Pilotage du club, membres, entrées, boutique et stock.'},reception:{label:'Réceptionniste',pages:['entries','clients','services'],description:'Accueil, contrôle des accès, inscriptions et renouvellements.'},seller:{label:'Vendeur',pages:['shop'],description:'Caisse boutique et suivi des commandes. Aucun accès aux profils fitness.'}};
let session={space:'hub',staffId:null,memberId:null},guestOrders=[],pendingOrder=null;
try{const saved=JSON.parse(sessionStorage.getItem('orion-session-v5-'+(window.ORION_ENTRY||'client')));if(saved)session=saved}catch{}
function migrateBase(){state.settings??={memberDiscount:10};state.staff??=[{id:'s1',name:'Alpha · Administration',role:'admin',enabled:true},{id:'s2',name:'Mariama · Direction',role:'manager',enabled:true},{id:'s3',name:'Fatou · Accueil',role:'reception',enabled:true},{id:'s4',name:'Oumar · Boutique',role:'seller',enabled:true}];state.members.forEach((m,i)=>{m.email??=`${m.id.toLowerCase()}@exemple.test`;m.birth??='';m.weight??='';m.address??='';m.goal??='';});}
const currentMember=()=>state.members.find(m=>m.id===session.memberId)||null;
const currentStaff=()=>state.staff.find(s=>s.id===session.staffId&&s.enabled)||null;
const can=feature=>{const r=currentStaff()?.role;return session.space==='staff'&&!!r&&({clients:['admin','manager','reception'],entries:['admin','manager','reception'],sales:['admin','manager','seller'],stock:['admin','manager'],team:['admin'],settings:['admin'],dashboard:['admin','manager']})[feature]?.includes(r)};
function deny(){toast('Cette action ne fait pas partie des droits de ce compte de démonstration.');return false}
function remember(){try{sessionStorage.setItem('orion-session-v5-'+(window.ORION_ENTRY||'client'),JSON.stringify(session))}catch{}}
function active(m){return !!m?.plan&&!!m.expiry&&m.expiry>=today()}
function go(p){const staffPages=roles[currentStaff()?.role]?.pages||[];if(session.space==='staff'){if(!currentStaff()){page='staffLogin'}else if(!staffPages.includes(p)){deny();return}else page=p;}else if(session.space==='client'){if(!['discover','shop','login','signup','fitness','myprofile','myorders','planning','training','progress','membership','program','coaching','wellness','body','insights','agenda','journal','more'].includes(p)){deny();return}page=['fitness','myprofile','myorders','planning','training','progress','membership','program','coaching','wellness','body','insights','agenda','journal','more'].includes(p)&&!currentMember()?'login':p;}else page='hub';search='';filter='Tous';accessMessage=null;remember();window.location.hash=(session.space==='staff'?'gestion':session.space==='client'?'client':'accueil')+'/'+page;render();window.scrollTo(0,0)}
function chooseSpace(space){session={space,staffId:null,memberId:null};cart={};pendingOrder=null;shopCustomer='walkin';shopMode='catalog';$('#modal').close();go(space==='staff'?'staffLogin':'discover')}
function logout(){session.memberId=null;session.staffId=null;cart={};pendingOrder=null;shopCustomer='walkin';go(session.space==='staff'?'staffLogin':'discover')}
function hub(){return`<section class="portal"><div class="portalbrand">✧ <span>ORION DISTRICT</span></div><div class="portalcopy"><div class="eyebrow">Sonfonia T7 · Conakry</div><h1>Votre club.<br>Votre espace.</h1><p>Deux expériences pensées pour vous.<br>Choisissez celle que vous souhaitez découvrir.</p></div><div class="portalcards"><button class="portalcard" onclick="chooseSpace('client')"><span class="eyebrow">01 · L’expérience client</span><h2>Mon univers Orion ${icon('arrow')}</h2><p>Découvrir le club, rejoindre la communauté,<br>retrouver mon fitness et faire mes achats.</p><span class="portalhint">Visiteurs & membres</span></button><button class="portalcard staffchoice" onclick="chooseSpace('staff')"><span class="eyebrow">02 · L’équipe du club</span><h2>Espace de gestion ${icon('arrow')}</h2><p>Accueillir les membres, gérer la boutique<br>et piloter l’activité selon mon rôle.</p><span class="portalhint">Admin · Manager · Réception · Vente</span></button></div><div class="portalnote">Démonstration interactive · Comptes fictifs et connexions simulées</div></section>`}
function demoBar(){return`<div class="demobar"><span>ORION · DÉMO V3</span><span>Connexions et achats simulés · données dans ce navigateur</span><button onclick="chooseSpace('hub')">Choisir un espace ${icon('arrow')}</button></div>`}
function render(){migrate();if(session.space==='staff'&&!currentStaff())page='staffLogin';if(session.space==='client'&&['fitness','myprofile','myorders','planning','training','progress','membership','program','coaching','wellness','body','insights','agenda','journal','more'].includes(page)&&!currentMember())page='login';let content;if(session.space==='hub'){content=hub()}else if(session.space==='staff'){content=page==='staffLogin'?demoBar()+staffLoginPage():staffShell()}else{content=clientShell()}$('#app').innerHTML=content;bindSearch()}
function staffLoginPage(){return`<main class="loginlayout"><div class="loginvisual"><span class="eyebrow">Orion District · Équipe</span><h1>Un club bien géré.<br>Une équipe bien entourée.</h1><p>Chaque métier dispose de son espace et de ses outils.</p><img src="building.png" alt="Complexe Orion District"></div><section class="loginform"><span class="eyebrow">Espace de gestion</span><h2>Choisir un compte démo</h2><p class="muted">Testez les droits de chaque membre de l’équipe.</p><div class="rolecards">${state.staff.filter(s=>s.enabled).map(s=>`<button class="rolecard" onclick="loginStaff('${s.id}')"><span class="avatar">${esc(initials(s.name))}</span><span><b>${esc(s.name)}</b><small>${roles[s.role].label}</small><p>${roles[s.role].description}</p></span>${icon('arrow')}</button>`).join('')}</div><p class="subtle">Sélection de compte pour la démonstration. Aucune authentification réelle ni protection serveur des rôles n’est activée.</p></section></main>`}
function loginStaff(id){const s=state.staff.find(s=>s.id===id&&s.enabled);if(!s)return;session={space:'staff',staffId:id,memberId:null};cart={};shopMode='catalog';go(roles[s.role].pages[0])}
function staffShell(){const s=currentStaff(),nav=[['dashboard','chart','Tableau de bord'],['entries','scan','Entrées & sorties'],['clients','users','Clients & abonnements'],['services','clock','Rendez-vous & machines'],['shop','bag','Boutique & caisse'],['team','users','Comptes de l’équipe'],['settings','card','Avantages membres']].filter(n=>roles[s.role].pages.includes(n[0]));if(!nav.some(n=>n[0]===page))page=nav[0][0];let contents=({dashboard,entries,clients,services:servicesPage,shop,team:teamPage,settings:settingsPage})[page]();return demoBar()+`<div class="shell staffshell"><aside class="sidebar"><div class="brand"><div class="brandmark">✧</div><div class="brandname">ORION<small>D I S T R I C T</small></div></div><div class="navlabel">Gestion · ${roles[s.role].label}</div><nav class="nav" aria-label="Gestion">${nav.map(([p,i,t])=>`<button class="${p===page?'active':''}" onclick="go('${p}')">${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebottom"><div class="sidecard"><span class="badge vip">${roles[s.role].label}</span><p>${roles[s.role].description}</p></div><div class="sidefooter"><span class="avatar">${esc(initials(s.name))}</span><div>${esc(s.name)}<small>Équipe Orion</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Espace de gestion / <b>${nav.find(n=>n[0]===page)[2]}</b></div><span class="mobilebrand">ORION · GESTION</span><div class="topright"><span class="badge">${roles[s.role].label}</span><button class="textbtn logout" onclick="logout()">Déconnexion ${icon('exit')}</button></div></header><main class="main">${contents}<footer class="footer"><span>Orion District · Gestion du club</span><span>Comptes fictifs · Droits simulés</span>${can('settings')?'<button class="textbtn" onclick="resetDemo()">Réinitialiser la démo</button>':''}</footer></main></div></div>`}
function publicClientShell(){const m=currentMember(),nav=[['discover','Le club'],...(m?[['fitness','Mon fitness']]:[]),['shop','Boutique'],...(m?[['myorders','Mes achats'],['myprofile','Mon profil']]:[])];const funcs={discover:discoverPage,shop,login:clientLoginPage,signup:signupPage,fitness:fitnessPage,myprofile:personalProfile,myorders:myOrdersPage};if(!funcs[page])page='discover';return demoBar()+`<div class="clientapp"><header class="clientheader"><button class="clientlogo" onclick="go('discover')"><span>✧</span> ORION <small>DISTRICT</small></button><nav aria-label="Espace client">${nav.map(([p,t])=>`<button class="${page===p?'active':''}" onclick="go('${p}')">${t}</button>`).join('')}</nav><div class="clientaccount">${m?`<span class="avatar">${esc(initials(m.name))}</span><button class="textbtn" onclick="logout()">Déconnexion</button>`:`<button class="btn" onclick="go('login')">Me connecter</button><button class="btn primary" onclick="go('signup')">Créer mon compte</button>`}</div></header><main class="clientmain">${funcs[page]()}</main><footer class="clientfooter"><div class="eyebrow">ORION DISTRICT</div><span>Sonfonia T7 · Conakry<br>Votre sport. Votre rythme. Votre communauté.</span><span>Prototype · Informations et prix indicatifs<br>Utilisez des données fictives pour vos essais.</span></footer></div>`}
function plansBlock(){return`<div class="plans">${[['Standard',35,['Tous les espaces sportifs','Cours collectifs programmés','Massage et pesée : option +6 $']],['Premium',100,['Tous les avantages Standard','Massage et programme nutritionnel','1 coaching par semaine']],['VIP',150,['Tous les avantages Premium','2 coachings par semaine','1 invité par visite']]].map(([p,n,features])=>`<article class="plan ${p.toLowerCase()}"><div class="eyebrow">${p}</div><div class="price">${money(n)} <small>/ mois</small></div><ul>${features.map(f=>`<li>${f}</li>`).join('')}</ul>${!currentMember()?`<button class="btn" onclick="go('signup');$('#signupPlan').value='${p}'">Choisir ${p} ${icon('arrow')}</button>`:''}</article>`).join('')}</div>`}
function discoverPage(){return`<section class="clienthero"><img src="building.png" alt="Vue du futur complexe Orion District"><div><span class="eyebrow">Fitness · Bien-être · Lifestyle</span><h1>Plus qu’une salle.<br>Votre nouveau rythme.</h1><p>Un lieu pour vous dépasser, prendre soin de vous<br>et retrouver l’essentiel, à Sonfonia T7.</p><div class="actions">${button(currentMember()?'Ouvrir mon fitness':'Rejoindre Orion',currentMember()?"go('fitness')":"go('signup')",'gold','arrow')}${button('Explorer la boutique',"go('shop')",'glass','bag')}</div></div><span class="phototag">Vue du projet · Ouverture à confirmer</span></section><div class="benefitrow"><span>${icon('pin')}Sonfonia T7, Conakry</span><span>${icon('clock')}Horaires envisagés : 6 h – 23 h</span><span>${icon('card')}3 formules pour votre rythme</span></div><section class="sectionintro"><span class="eyebrow">Votre prochaine étape</span><h2>Trouvez votre formule.</h2><p>Du premier entraînement à votre nouvelle routine, Orion vous accompagne.</p></section>${plansBlock()}<div class="shopteaser"><div><span class="eyebrow">La boutique Orion</span><h2>Bien équipé. Prêt à avancer.</h2><p>Vêtements, accessoires et essentiels sportifs accessibles à tous.${state.settings.memberDiscount>0?`<br>Membre actif connecté ? Profitez de ${state.settings.memberDiscount} % de remise démo.`:''}</p></div>${button('Découvrir la sélection',"go('shop')",'primary','bag')}</div><p class="subtle">Tarifs du business plan en dollars, grille en GNF à valider. Remise membre proposée pour cette démo.</p>`}
function clientLoginPage(){return`<div class="authwrap"><section class="panel authpanel"><span class="eyebrow">Votre espace personnel</span><h1>Heureux de vous revoir.</h1><p>Connectez votre compte démo pour retrouver votre fitness, votre profil et vos avantages boutique.</p><form onsubmit="event.preventDefault();loginClient()"><div class="field"><label for="loginEmail">Adresse e-mail du compte démo</label><input id="loginEmail" type="email" autocomplete="off" required placeholder="od-001@exemple.test"></div><button class="btn primary" type="submit">Entrer dans mon espace ${icon('arrow')}</button></form><div class="quickaccounts"><span class="eyebrow">Essayer un profil</span><button onclick="loginClient('OD-001')">Aïssatou · Premium actif ${icon('arrow')}</button><button onclick="loginClient('OD-005')">Mariama · Abonnement expiré ${icon('arrow')}</button></div><p class="subtle">Connexion simulée, sans mot de passe. Utilisez uniquement des informations fictives.</p><button class="textbtn" onclick="go('signup')">Pas encore de compte ? Créer mon compte</button></section></div>`}
function loginClient(id){const m=id?state.members.find(m=>m.id===id):state.members.find(m=>m.email.toLowerCase()===$('#loginEmail').value.trim().toLowerCase());if(!m){toast('Aucun compte démo trouvé avec cette adresse e-mail.');return}session={space:'client',staffId:null,memberId:m.id};shopCustomer=m.id;pendingOrder=null;go('fitness')}
function profileFields(m={},prefix='personal'){return`<div class="formrow"><div class="field"><label for="${prefix}Name">Nom complet *</label><input id="${prefix}Name" name="name" required maxlength="80" value="${esc(m.name||'')}" autocomplete="off"></div><div class="field"><label for="${prefix}Email">Adresse e-mail *</label><input id="${prefix}Email" name="email" type="email" required maxlength="120" value="${esc(m.email||'')}" autocomplete="off"></div></div><div class="formrow"><div class="field"><label for="${prefix}Phone">Téléphone</label><input id="${prefix}Phone" name="phone" type="tel" maxlength="25" value="${esc(m.phone||'')}"></div><div class="field"><label for="${prefix}Birth">Date de naissance</label><input id="${prefix}Birth" name="birth" type="date" max="${today()}" value="${esc(m.birth||'')}"></div></div><div class="field"><label for="${prefix}Address">Adresse</label><input id="${prefix}Address" name="address" maxlength="200" value="${esc(m.address||'')}" placeholder="Quartier, ville"></div><div class="formrow"><div class="field"><label for="${prefix}Weight">Poids (kg) · facultatif</label><input id="${prefix}Weight" name="weight" type="number" min="20" max="400" step="0.1" value="${esc(m.weight||'')}" placeholder="Ex. 72,5"></div><div class="field"><label for="${prefix}Goal">Mon objectif</label><select id="${prefix}Goal" name="goal">${['','Me remettre en forme','Gagner en force','Améliorer mon endurance','Bouger régulièrement'].map(g=>`<option value="${g}" ${m.goal===g?'selected':''}>${g||'Choisir un objectif'}</option>`).join('')}</select></div></div>`}
function signupPage(){return`<div class="profilelayout"><div class="profileintro"><span class="eyebrow">Bienvenue dans la communauté</span><h1>Votre histoire<br>commence ici.</h1><p>Créez votre profil pour retrouver vos achats et votre espace fitness. Vous pouvez commencer sans abonnement.</p><div class="notice">Démo : renseignez des informations fictives. Les données sont enregistrées uniquement dans ce navigateur.</div></div><section class="panel profileform"><h2>Créer mon compte</h2><form id="signupForm" onsubmit="event.preventDefault();registerMember()">${profileFields({},'signup')}<div class="field"><label for="signupPlan">Mon abonnement</label><select id="signupPlan" name="plan"><option value="">Sans abonnement · compte boutique</option>${Object.keys(planPrices).map(p=>`<option value="${p}">${p} · ${money(planPrices[p])} / mois</option>`).join('')}</select></div><p class="subtle">* Champs obligatoires. L’abonnement choisi sera activé fictivement pendant 30 jours, sans prélèvement.</p><button class="btn primary" style="margin-top:18px">Créer mon espace ${icon('arrow')}</button></form></section></div>`}
function profileData(form){const f=new FormData(form);return Object.fromEntries(['name','email','phone','birth','address','weight','goal'].map(k=>[k,String(f.get(k)||'').trim()]))}
function validProfile(d,exceptId){if(!d.name||!d.email||!/^\S+@\S+\.\S+$/.test(d.email)){toast('Renseignez un nom et une adresse e-mail valide.');return false}if(state.members.some(m=>m.id!==exceptId&&m.email.toLowerCase()===d.email.toLowerCase())){toast('Cette adresse e-mail possède déjà un compte.');return false}if(d.birth&&d.birth>today()){toast('La date de naissance ne peut pas être dans le futur.');return false}if(d.weight&&(Number(d.weight)<20||Number(d.weight)>400||!Number.isFinite(Number(d.weight)))){toast('Saisissez un poids entre 20 et 400 kg.');return false}return true}
function registerMember(){if(session.space!=='client')return deny();const d=profileData($('#signupForm'));if(!validProfile(d))return;const p=new FormData($('#signupForm')).get('plan');if(p&&!planPrices[p])return;const n=Math.max(0,...state.members.map(m=>Number(m.id.slice(3))))+1;let m={...d,id:'OD-'+String(n).padStart(3,'0'),plan:p||null,expiry:p?shift(30):null,created:today(),visits:0};state.members.push(m);if(p)state.payments.push({id:uid(),memberId:m.id,total:planPrices[p],time:new Date().toISOString(),type:'Inscription démo'});save();loginClient(m.id);toast('Votre espace personnel est prêt.')}
function personalProfile(){const m=currentMember();return heading('Mon profil','Mes informations personnelles et mon objectif fitness.')+`<div class="profilelayout"><aside class="panel profileintro"><span class="avatar bigavatar">${esc(initials(m.name))}</span><h2>${esc(m.name)}</h2><p>${m.id}<br>${m.plan||'Sans abonnement'}</p><div class="notice">Ces champs servent à illustrer votre futur profil client. Utilisez uniquement des données fictives.</div><p class="subtle">Le poids et l’objectif ne sont pas affichés aux vendeurs ni dans les fiches d’accueil.</p></aside><section class="panel profileform"><form id="personalForm" onsubmit="event.preventDefault();savePersonal()">${profileFields(m)}<div class="actions"><button class="btn primary">Enregistrer mon profil ${icon('check')}</button></div></form></section></div>`}
function savePersonal(){const m=currentMember();if(session.space!=='client'||!m)return deny();const d=profileData($('#personalForm'));if(!validProfile(d,m.id))return;Object.assign(m,d);save();render();toast('Votre profil a été mis à jour.')}
function discountRate(){const m=session.space==='client'?currentMember():null;return m&&active(m)?state.settings.memberDiscount:0}
const roundMoney=n=>Math.round((n+Number.EPSILON)*100)/100;
const sellingPrice=p=>roundMoney(p.price*(1-discountRate()/100));
function shop(){const client=session.space==='client';if(!client&&!can('sales'))return'<div class="empty">Boutique indisponible pour ce rôle.</div>';if(client)shopMode='catalog';const m=currentMember(),rate=discountRate();let products=state.products.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())&&(filter==='Tous'||p.category===filter));const modes=[['catalog','Catalogue & caisse'],...(can('stock')?[['stock','Stock']]:[]),['orders','Commandes']];return heading(client?'Votre boutique Orion.':'Boutique & caisse',client?'Les essentiels de votre prochaine séance.':'Ventes, préparation des commandes et disponibilité des articles.',client?'':`<div class="tabs">${modes.map(([v,t])=>`<button class="${shopMode===v?'active':''}" onclick="setShopMode('${v}')">${t}</button>`).join('')}</div>`)+(shopMode==='stock'&&can('stock')?stockPage():shopMode==='orders'?ordersPage():`${client?`<div class="shopidentity ${rate?'eligible':''}"><span>${icon(rate?'card':'bag')}<b>${m?esc(m.name):'Vous visitez la boutique'}</b> · ${rate?`Avantage membre actif : −${rate} %`:(m?'Tarifs publics · abonnement inactif':'Tarifs publics, accessibles à tous')}</span>${!m?'<button class="textbtn" onclick="go(\'login\')">Déjà membre ? Me connecter →</button>':'<button class="textbtn" onclick="go(\'fitness\')">Mon fitness →</button>'}</div>`:''}<div class="toolbar">${searchbar('Rechercher un article…')}<div class="tabs">${['Tous','Vêtements','Accessoires','Petit matériel','Nutrition'].map(t=>`<button class="${filter===t?'active':''}" onclick="filter='${t}';render()">${t}</button>`).join('')}</div></div><div class="split"><div class="cards">${products.map(p=>`<article class="product"><div class="productart">${p.stock<5?`<span class="badge ${p.stock?'vip':'red'}">${p.stock?p.stock+' derniers':'Épuisé'}</span>`:''}${art(p)}</div><div class="productinfo"><small>${esc(p.category)}</small><h3>${esc(p.name)}</h3><div class="productbottom"><div>${rate?`<del>${money(p.price)}</del> `:''}<b>${money(sellingPrice(p))}</b>${rate?'<small class="memberprice">Prix membre</small>':''}</div><button aria-label="Ajouter ${esc(p.name)} au panier" onclick="addCart('${p.id}')" ${p.stock<1?'disabled':''}>+</button></div></div></article>`).join('')||'<div class="empty">Aucun article trouvé.</div>'}</div>${cartPanel()}</div><p class="subtle" style="margin-top:18px">Articles et prix de démonstration. Remise proposée à titre d’exemple, configurable par l’administrateur.</p>`)}
function setShopMode(mode){if(mode==='stock'&&!can('stock'))return deny();if(!can('sales'))return deny();shopMode=mode;render()}
function cartTotals(){const items=state.products.filter(p=>cart[p.id]);const subtotal=roundMoney(items.reduce((s,p)=>s+p.price*cart[p.id],0)),total=roundMoney(items.reduce((s,p)=>s+sellingPrice(p)*cart[p.id],0));return{items,subtotal,total,discount:roundMoney(subtotal-total),rate:discountRate()}}
function cartPanel(){const{items,total,subtotal,discount,rate}=cartTotals(),m=currentMember(),client=session.space==='client';return`<aside class="panel cart"><div class="panelhead"><h2>Votre panier</h2><span class="badge">${Object.values(cart).reduce((s,n)=>s+n,0)} article(s)</span></div><div class="cartbody">${items.length?items.map(p=>`<div class="cartrow"><span class="thumb">${art(p)}</span><div><h3>${esc(p.name)}</h3><div class="qty"><button aria-label="Retirer un ${esc(p.name)}" onclick="changeQty('${p.id}',-1)">−</button>${cart[p.id]}<button aria-label="Ajouter un ${esc(p.name)}" onclick="changeQty('${p.id}',1)">+</button></div></div><strong>${money(sellingPrice(p)*cart[p.id])}</strong></div>`).join(''):'<div class="empty">Ajoutez vos essentiels.<br>Votre prochaine séance vous attend.</div>'}${rate?`<div class="priceline"><span>Sous-total public</span><span>${money(subtotal)}</span></div><div class="priceline saving"><span>Remise membre · ${rate} %</span><b>−${money(discount)}</b></div>`:''}<div class="carttotal"><span>Total</span><b>${money(total)}</b></div>${client?`<div class="buyeridentity">${icon('users')}<div><small>Commande pour</small><b>${m?esc(m.name):'Visiteur · sans compte'}</b></div></div>`:`<div class="field"><label for="customer">Compte client</label><select id="customer" onchange="shopCustomer=this.value"><option value="walkin" ${shopCustomer==='walkin'?'selected':''}>Client de passage</option>${state.members.map(m=>`<option value="${m.id}" ${shopCustomer===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div>`}<button class="btn primary" onclick="checkout()" ${items.length?'':'disabled'}>Commander · ${money(total)} ${icon('arrow')}</button><p class="subtle" style="text-align:center;margin-top:13px">Retrait à la boutique · Paiement simulé</p></div></aside>`}
function checkout(){if(session.space!=='client'&&!can('sales'))return deny();const t=cartTotals();if(!t.items.length)return;if(t.items.some(p=>cart[p.id]>p.stock)){toast('Le stock a changé. Ajustez votre panier.');return}pendingOrder={memberId:session.space==='client'?(currentMember()?.id||'walkin'):shopCustomer,space:session.space,staffId:session.staffId,rate:t.rate,total:t.total,subtotal:t.subtotal,discount:t.discount,items:t.items.map(p=>({id:p.id,name:p.name,qty:cart[p.id],publicPrice:p.price,price:sellingPrice(p)}))};modal('Confirmer la commande',`<div class="receipt"><h2>${money(t.total)}</h2><p>${t.items.map(p=>esc(p.name)+' × '+cart[p.id]).join('<br>')}</p>${t.rate?`<p class="saving">Votre remise membre : ${money(t.discount)} (${t.rate} %)</p>`:''}<p>Retrait sur place à Sonfonia T7.</p></div><div class="notice">Achat de démonstration, sans prélèvement réel.</div><div class="actions"><button class="btn" onclick="$('#modal').close()">Retour</button><button class="btn primary" onclick="confirmOrder()">Valider l’achat démo</button></div>`)}
function confirmOrder(){const o=pendingOrder;if(!o)return;const buyer=session.space==='client'?(currentMember()?.id||'walkin'):shopCustomer;if((session.space!=='client'&&!can('sales'))||o.space!==session.space||o.memberId!==buyer||o.staffId!==session.staffId||o.rate!==discountRate())return deny();if(o.items.some(i=>!state.products.find(p=>p.id===i.id)||state.products.find(p=>p.id===i.id).stock<i.qty)){toast('Stock insuffisant : vérifiez le panier.');return}const order={...o,id:'OR-'+String(state.orders.length+1).padStart(4,'0'),time:new Date().toISOString(),status:'À retirer'};o.items.forEach(i=>state.products.find(p=>p.id===i.id).stock-=i.qty);state.orders.unshift(order);if(buyer==='walkin')guestOrders.push(order.id);pendingOrder=null;cart={};save();render();modal('Commande confirmée',`<div class="receipt"><div class="check">${icon('check')}</div><h2>Merci pour votre achat !</h2><p>${order.id} · ${money(order.total)}<br>Retrait à la boutique Orion District.</p>${o.discount?`<p>Vous avez économisé ${money(o.discount)} grâce à votre abonnement.</p>`:''}<div class="notice">Commande fictive enregistrée. Le stock a été mis à jour.</div><button class="btn primary" onclick="$('#modal').close()">Continuer</button></div>`)}
function myOrdersPage(){const m=currentMember(),orders=state.orders.filter(o=>o.memberId===m.id);return heading('Mes achats','Toutes mes commandes boutique, au même endroit.')+`<section class="panel"><div class="tablewrap"><table><thead><tr><th>Commande</th><th>Articles</th><th>Avantage membre</th><th>Total</th><th>Retrait</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${o.id}<br><small>${date(o.time.slice(0,10))}</small></td><td>${o.items.map(i=>esc(i.name)+' × '+i.qty).join('<br>')}</td><td>${o.discount?'−'+money(o.discount):'—'}</td><td>${money(o.total)}</td><td><span class="badge green">${o.status}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Votre première commande vous attend dans la boutique.</td></tr>'}</tbody></table></div></section>`}
function teamPage(){if(!can('team'))return'';return heading('Les bons outils, pour chaque métier.','Comptes de démonstration et répartition des responsabilités.',button('Ajouter un compte','staffForm()'))+`<div class="roleoverview">${Object.entries(roles).map(([k,r])=>`<article class="panel"><span class="eyebrow">${r.label}</span><p>${r.description}</p></article>`).join('')}</div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Compte</th><th>Rôle</th><th>Statut</th><th></th></tr></thead><tbody>${state.staff.map(s=>`<tr><td>${esc(s.name)}${s.id===session.staffId?' <span class="badge">Vous</span>':''}</td><td>${roles[s.role].label}</td><td><span class="badge ${s.enabled?'green':'red'}">${s.enabled?'Actif':'Désactivé'}</span></td><td><button class="btn small" onclick="staffForm('${s.id}')" ${s.id===session.staffId?'disabled':''}>Modifier</button></td></tr>`).join('')}</tbody></table></div></section><div class="notice">Les rôles filtrent les écrans et les actions de cette démo. Une authentification et des autorisations côté serveur seront nécessaires pour l’exploitation réelle.</div>`}
function staffForm(id){if(!can('team'))return deny();const s=state.staff.find(s=>s.id===id)||{name:'',role:'seller',enabled:true};if(id===session.staffId)return deny();modal(id?'Modifier le compte':'Nouveau compte d’équipe',`<form id="staffForm" onsubmit="event.preventDefault();saveStaff('${id||''}')"><div class="field"><label for="staffName">Nom affiché</label><input id="staffName" name="name" required maxlength="80" value="${esc(s.name)}"></div><div class="field"><label for="staffRole">Rôle</label><select id="staffRole" name="role">${Object.entries(roles).map(([k,r])=>`<option value="${k}" ${s.role===k?'selected':''}>${r.label}</option>`).join('')}</select></div><div class="field"><label for="staffEnabled">Statut</label><select id="staffEnabled" name="enabled"><option value="yes" ${s.enabled?'selected':''}>Actif</option><option value="no" ${!s.enabled?'selected':''}>Désactivé</option></select></div><button class="btn primary">Enregistrer le compte démo</button></form>`)}
function saveStaff(id){if(!can('team')||id===session.staffId)return deny();const f=new FormData($('#staffForm')),name=String(f.get('name')).trim(),role=f.get('role');if(!name||!roles[role])return;const data={name,role,enabled:f.get('enabled')==='yes'};if(id)Object.assign(state.staff.find(s=>s.id===id),data);else state.staff.push({id:'s'+uid(),...data});save();$('#modal').close();render();toast('Compte d’équipe enregistré.')}
function settingsPage(){if(!can('settings'))return'';return heading('Les avantages de votre communauté.','Configurez la remise proposée aux membres dans la boutique.')+`<section class="panel settingspanel"><span class="eyebrow">Boutique · Membres actifs</span><h2>Une remise qui suit le membre.</h2><p>Lorsqu’un client connecté ouvre la boutique depuis son espace fitness, son identité et son abonnement sont conservés. La réduction apparaît sur les articles, dans le panier et dans la commande.</p><form onsubmit="event.preventDefault();saveDiscount()"><div class="field"><label for="discountValue">Remise membre (%)</label><input id="discountValue" type="number" min="0" max="50" step="1" value="${state.settings.memberDiscount}" required></div><button class="btn primary">Enregistrer la remise</button></form><div class="notice">S’applique à tous les articles pour les comptes clients connectés avec un abonnement actif. Visiteurs, abonnements expirés et caisse de gestion : tarif public. Les anciennes commandes conservent leur prix.</div></section>`}
function saveDiscount(){if(!can('settings'))return deny();let n=Number($('#discountValue').value);if(!Number.isInteger(n)||n<0||n>50){toast('Choisissez un pourcentage entier entre 0 et 50.');return}state.settings.memberDiscount=n;save();render();toast('Remise membre mise à jour.')}
function profile(id){if(!can('clients'))return deny();const m=state.members.find(m=>m.id===id);modal('Fiche client',`<div class="profilehead"><span class="avatar">${esc(initials(m.name))}</span><div><h2>${esc(m.name)}</h2><p>${m.id} · ${m.plan?planBadge(m.plan):'Sans abonnement'}</p></div></div><div class="details"><div><small>E-mail</small><b>${esc(m.email)}</b></div><div><small>Téléphone</small><b>${esc(m.phone)||'Non renseigné'}</b></div><div><small>Date de naissance</small><b>${m.birth?date(m.birth):'Non renseignée'}</b></div><div><small>Fin d’abonnement</small><b>${m.expiry?date(m.expiry):'Aucun abonnement'}</b></div></div><p class="subtle">Adresse : ${esc(m.address)||'Non renseignée'}</p><div class="actions"><button class="btn" onclick="editClient('${id}')">Coordonnées</button><button class="btn primary" onclick="subscriptionForm('${id}')">${m.plan?'Renouveler':'Activer un abonnement'}</button></div>`)}
function subscriptionForm(id){if(!can('clients'))return deny();const m=state.members.find(m=>m.id===id);modal('Abonnement client',`<form onsubmit="event.preventDefault();applySubscription('${id}')"><div class="field"><label for="subscriptionPlan">Formule pour 30 jours</label><select id="subscriptionPlan">${Object.keys(planPrices).map(p=>`<option value="${p}" ${m.plan===p?'selected':''}>${p} · ${money(planPrices[p])}</option>`).join('')}</select></div><div class="notice">Même formule : 30 jours ajoutés à l’échéance active. Nouvelle formule ou abonnement expiré : 30 jours à partir d’aujourd’hui. Paiement simulé.</div><button class="btn primary">Confirmer l’abonnement démo</button></form>`)}
function applySubscription(id){if(!can('clients'))return deny();const m=state.members.find(m=>m.id===id),p=$('#subscriptionPlan').value;if(!planPrices[p])return;const base=m.plan===p&&active(m)?m.expiry:today();m.plan=p;m.expiry=shift(30,base);state.payments.push({id:uid(),memberId:id,total:planPrices[p],time:new Date().toISOString(),type:'Abonnement'});save();render();profile(id);toast('Abonnement mis à jour.')}
function doReset(){if(!can('settings'))return deny();state=seed();migrate();cart={};pendingOrder=null;session={space:'hub',staffId:null,memberId:null};save();remember();$('#modal').close();go('hub');toast('Démonstration réinitialisée.')}
function routeFromHash(){const parts=window.location.hash.replace(/^#/,'').split('/');if(parts[0]==='gestion'){session.space='staff';page=currentStaff()&&roles[currentStaff().role].pages.includes(parts[1])?parts[1]:'staffLogin'}else if(parts[0]==='client'){session.space='client';page=['discover','shop','login','signup','fitness','myprofile','myorders','planning','training','progress','membership','program','coaching','wellness','body','insights','agenda','journal','more'].includes(parts[1])?parts[1]:'discover'}else{session.space='hub';page='hub'}render()}

function inviteMyGuest(){const m=currentMember();if(session.space!=='client'||!m||m.plan!=='VIP'||!active(m))return deny();if(!state.entries.some(e=>e.memberId===m.id&&!e.guest&&!e.out)){toast('Présentez votre pass à l’accueil avant de faire entrer votre invité.');return}if(state.entries.some(e=>e.memberId===m.id&&e.guest&&!e.out)){toast('Un invité est déjà présent pour cette visite.');return}modal('Mon invité VIP',`<form id="guestForm" onsubmit="event.preventDefault();admitMyGuest()"><div class="field"><label for="guestName">Nom de votre proche</label><input id="guestName" name="name" required maxlength="80"></div><div class="notice">Un invité à la fois, accompagné du membre VIP. Accès simulé pour cette visite ; coaching personnel non inclus.</div><button class="btn primary">Valider l’invitation démo</button></form>`)}
function admitMyGuest(){const m=currentMember();if(session.space!=='client'||!m||m.plan!=='VIP'||!active(m)||!state.entries.some(e=>e.memberId===m.id&&!e.guest&&!e.out)||state.entries.some(e=>e.memberId===m.id&&e.guest&&!e.out))return deny();const name=String(new FormData($('#guestForm')).get('name')||'').trim();if(!name)return;state.entries.unshift({id:uid(),memberId:m.id,name,plan:'Invité VIP',time:new Date().toISOString(),out:null,guest:true});save();$('#modal').close();render();toast('Votre proche est enregistré pour cette visite.')}
